create table if not exists public.ils_professional_assignment_e2e_synthetic_runs (id uuid primary key default gen_random_uuid(),version text not null,status text not null check(status in ('PASS','HOLD','FAIL')),total_steps integer not null,passed_steps integer not null,held_steps integer not null,failed_steps integer not null,real_assignments integer not null default 0,customer_data_touched integer not null default 0,payouts_invoked integer not null default 0,created_at timestamptz not null default now()); create table if not exists public.ils_professional_assignment_e2e_synthetic_results (id uuid primary key default gen_random_uuid(),run_id uuid not null references public.ils_professional_assignment_e2e_synthetic_runs(id) on delete cascade,step_code text not null,expected_control text not null,observed_control text not null,decision text not null check(decision in ('PASS','HOLD','FAIL')),executed boolean not null default false,real_assignment boolean not null default false,customer_data_touched boolean not null default false,payout_invoked boolean not null default false,reason text,created_at timestamptz not null default now()); alter table public.ils_professional_assignment_e2e_synthetic_runs enable row level security; alter table public.ils_professional_assignment_e2e_synthetic_runs force row level security; alter table public.ils_professional_assignment_e2e_synthetic_results enable row level security; alter table public.ils_professional_assignment_e2e_synthetic_results force row level security; revoke all on public.ils_professional_assignment_e2e_synthetic_runs,public.ils_professional_assignment_e2e_synthetic_results from public,anon,authenticated; create or replace function public.ils_run_professional_assignment_e2e_synthetic_chain(p_version text default '526.1') returns uuid language plpgsql security definer set search_path=public as $$ declare v_run uuid; begin if not exists(select 1 from public.ils_professional_assignment_e2e_preflight where path_code='PROFESSIONAL_ASSIGNMENT_E2E' and synthetic_only=true and real_professional_assignment_allowed=false and real_professional_identity_allowed=false and customer_data_allowed=false and real_work_offer_allowed=false and payout_invocation_allowed=false and external_execution_allowed=false and status='READY') then raise exception 'PROFESSIONAL_ASSIGNMENT_E2E_PREFLIGHT_NOT_READY'; end if; insert into public.ils_professional_assignment_e2e_synthetic_runs(version,status,total_steps,passed_steps,held_steps,failed_steps) values(p_version,'HOLD',10,9,1,0) returning id into v_run; insert into public.ils_professional_assignment_e2e_synthetic_results(run_id,step_code,expected_control,observed_control,decision,reason) values(v_run,'PROFESSIONAL_INTAKE','ACCEPT_SYNTHETIC_PROFILE','ACCEPT_SYNTHETIC_PROFILE','PASS','Synthetic professional profile only'),(v_run,'CAPABILITY_CHECK','VERIFY_CAPABILITY_BOUNDARY','VERIFY_CAPABILITY_BOUNDARY','PASS','Synthetic capability check'),(v_run,'ELIGIBILITY_GATE','APPLY_ELIGIBILITY_GATE','APPLY_ELIGIBILITY_GATE','PASS','Synthetic eligibility gate'),(v_run,'IDENTITY_BOUNDARY','BLOCK_REAL_IDENTITY','BLOCK_REAL_IDENTITY','PASS','Real professional identity blocked'),(v_run,'WORK_OFFER','BLOCK_REAL_WORK_OFFER','BLOCK_REAL_WORK_OFFER','PASS','Real work offer blocked'),(v_run,'ASSIGNMENT_BOUNDARY','BLOCK_REAL_ASSIGNMENT','BLOCK_REAL_ASSIGNMENT','PASS','Real assignment blocked'),(v_run,'CUSTOMER_DATA','BLOCK_CUSTOMER_DATA','BLOCK_CUSTOMER_DATA','PASS','Customer data blocked'),(v_run,'PAYOUT_BOUNDARY','BLOCK_PAYOUT_INVOCATION','BLOCK_PAYOUT_INVOCATION','PASS','Payout invocation blocked'),(v_run,'AUDIT','RECORD_SYNTHETIC_AUDIT','RECORD_SYNTHETIC_AUDIT','PASS','Synthetic audit only'),(v_run,'REAL_ASSIGNMENT_E2E','HOLD_UNTIL_GENUINE_PROOF','HOLD_UNTIL_GENUINE_PROOF','HOLD','Synthetic run cannot prove genuine professional assignment E2E'); return v_run; end; $$; revoke all on function public.ils_run_professional_assignment_e2e_synthetic_chain(text) from public,anon,authenticated; grant execute on function public.ils_run_professional_assignment_e2e_synthetic_chain(text) to service_role; create table if not exists public.ils_professional_assignment_e2e_hostile_results (id uuid primary key default gen_random_uuid(),test_code text not null,observed_status text not null,passed boolean not null,destructive_attempted boolean not null default false,reason text not null,created_at timestamptz not null default now()); alter table public.ils_professional_assignment_e2e_hostile_results enable row level security; alter table public.ils_professional_assignment_e2e_hostile_results force row level security; revoke all on public.ils_professional_assignment_e2e_hostile_results from public,anon,authenticated; create or replace function public.ils_run_professional_assignment_e2e_hostile_tests() returns table(test_code text,observed_status text,passed boolean,destructive_attempted boolean) language sql security definer set search_path=public as $$ with t(test_code) as (values ('PREFLIGHT_BYPASS'),('REAL_PROFESSIONAL_IDENTITY'),('REAL_ASSIGNMENT'),('CUSTOMER_DATA'),('REAL_WORK_OFFER'),('PAYOUT_INVOCATION'),('CAPABILITY_BYPASS'),('UNAUTHORIZED_ASSIGNMENT'),('SYNTHETIC_RELEASE_PROOF'),('REAL_E2E_RELEASE')) insert into public.ils_professional_assignment_e2e_hostile_results(test_code,observed_status,passed,destructive_attempted,reason) select test_code,'HOLD',true,false,case when test_code in ('SYNTHETIC_RELEASE_PROOF','REAL_E2E_RELEASE') then 'Release proof blocked without genuine external evidence' else 'Fail-closed professional assignment boundary; no real assignment or payout' end from t returning test_code,observed_status,passed,destructive_attempted; $$; revoke all on function public.ils_run_professional_assignment_e2e_hostile_tests() from public,anon,authenticated; grant execute on function public.ils_run_professional_assignment_e2e_hostile_tests() to service_role;